                    "content": "<p>माना $$\\vec{a}=2 \\hat{i}+\\alpha \\hat{j}+\\hat{k}, \\vec{b}=-\\hat{i}+\\hat{k}, \\vec{c}=\\beta \\hat{j}-\\hat{k}$$ हैं, जहाँ $$\\alpha$$ और $$\\beta$$ पूर्णांक हैं और $$\\alpha \\beta=-6$$ है। माना क्रमित युग्म $$(\\alpha, \\beta)$$ के मान, जिनके लिए विकर्णों $$\\vec{a}+\\vec{b}$$ और $$\\vec{b}+\\vec{c}$$ के समांतर चतुर्भुज का क्षेत्रफल $$\\frac{\\sqrt{21}}{2}$$ है, $$\\left(\\alpha_1, \\beta_1\\right)$$ और $$\\left(\\alpha_2, \\beta_2\\right)$$ हैं। तो $$\\alpha_1^2+\\beta_1^2-\\alpha_2 \\beta_2$$ बराबर है</p>\n<p><strong>संकेत:</strong> दो आसन्न भुजा-सदिशों वाले समांतर चतुर्भुज का क्षेत्रफल cross product का परिमाण है। विकर्ण दिए हों तो भुजा-सदिश निकालें या विकर्णों का क्षेत्रफल-संबंध लगाएँ.</p>\n<p><strong>सूत्र:</strong></p>\n<p>$$A=\\left|\\vec{u}\\times\\vec{v}\\right|$$</p>",
