                    "content": "<p>The sum of the coefficients of $$x^{2 / 3}$$ and $$x^{-2 / 5}$$ in the binomial expansion of $$\\left(x^{2 / 3}+\\frac{1}{2} x^{-2 / 5}\\right)^9$$ is</p>\n<p><strong>Hint:</strong> Write the general term and match its power of $x$ to the requested exponent. The coefficient is the numerical factor of that matching term.</p>\n<p><strong>Formula:</strong></p>\n<p>$$T_{r+1}=\\binom{n}{r}a^{n-r}b^r$$</p>",
