                    "content": "<p>If $$\\log _e y=3 \\sin ^{-1} x$$, then $$(1-x^2) y^{\\prime \\prime}-x y^{\\prime}$$ at $$x=\\frac{1}{2}$$ is equal to</p>\n<p><strong>Hint:</strong> Differentiate logarithmically first, then differentiate again only as needed. Substitute the given value after obtaining expressions for $y'$ and $y''$.</p>\n<p><strong>Formula:</strong></p>\n<p>$$\\frac{d}{dx}\\bigl(\\sin^{-1}x\\bigr)=\\frac{1}{\\sqrt{1-x^2}},\\qquad \\frac{y'}{y}=\\frac{d}{dx}(\\ln y)$$</p>",
