                    "content": "<p>Let $$\\alpha, \\beta ; \\alpha>\\beta$$, be the roots of the equation $$x^2-\\sqrt{2} x-\\sqrt{3}=0$$. Let $$\\mathrm{P}_n=\\alpha^n-\\beta^n, n \\in \\mathrm{N}$$. Then $$(11 \\sqrt{3}-10 \\sqrt{2}) \\mathrm{P}_{10}+(11 \\sqrt{2}+10) \\mathrm{P}_{11}-11 \\mathrm{P}_{12}$$ is equal to</p>\n<p><strong>Hint:</strong> Use the quadratic equation to obtain a recurrence for powers of its roots. Multiply the recurrence by the required terms to simplify the expression involving $P_n$.</p>\n<p><strong>Formula:</strong></p>\n<p>$$\\alpha^2-(\\alpha+\\beta)\\alpha+\\alpha\\beta=0,\\qquad P_{n+2}=(\\alpha+\\beta)P_{n+1}-\\alpha\\beta P_n$$</p>",
