                    "content": "<p>माना समीकरण $$x^2-\\sqrt{2} x-\\sqrt{3}=0$$ के मूल $$\\alpha, \\beta ; \\alpha>\\beta$$ हैं। माना $$\\mathrm{P}_n=\\alpha^n-\\beta^n, n \\in \\mathrm{N}$$ है। तो $$(11 \\sqrt{3}-10 \\sqrt{2}) \\mathrm{P}_{10}+(11 \\sqrt{2}+10) \\mathrm{P}_{11}-11 \\mathrm{P}_{12}$$ बराबर है</p>\n<p><strong>संकेत:</strong> द्विघात समीकरण से मूलों की घातों के लिए recurrence निकालें। $P_n$ वाले व्यंजक को सरल करने के लिए recurrence को उपयुक्त पदों से गुणा करें.</p>\n<p><strong>सूत्र:</strong></p>\n<p>$$P_{n+2}=(\\alpha+\\beta)P_{n+1}-\\alpha\\beta P_n$$</p>",
