                    "content": "<p>If the variance of the frequency distribution</p>\n<p><style type=\"text/css\">\n.tg  {border-collapse:collapse;border-spacing:0;}\n.tg td{border-color:black;border-style:solid;border-width:1px;font-family:Arial, sans-serif;font-size:14px;\n  overflow:hidden;padding:10px 5px;word-break:normal;}\n.tg th{border-color:black;border-style:solid;border-width:1px;font-family:Arial, sans-serif;font-size:14px;\n  font-weight:normal;overflow:hidden;padding:10px 5px;word-break:normal;}\n.tg .tg-baqh{text-align:center;vertical-align:top}\n</style>\n<table class=\"tg\" style=\"undefined;table-layout: fixed; width: 492px\">\n<colgroup>\n<col style=\"width: 70px\">\n<col style=\"width: 68px\">\n<col style=\"width: 70px\">\n<col style=\"width: 70px\">\n<col style=\"width: 69px\">\n<col style=\"width: 72px\">\n<col style=\"width: 73px\">\n</colgroup>\n<thead>\n  <tr>\n    <th class=\"tg-baqh\">$$x$$</th>\n    <th class=\"tg-baqh\">$$c$$</th>\n    <th class=\"tg-baqh\">$$2c$$</th>\n    <th class=\"tg-baqh\">$$3c$$</th>\n    <th class=\"tg-baqh\">$$4c$$</th>\n    <th class=\"tg-baqh\">$$5c$$</th>\n    <th class=\"tg-baqh\">$$6c$$</th>\n  </tr>\n</thead>\n<tbody>\n  <tr>\n    <td class=\"tg-baqh\">$$f$$</td>\n    <td class=\"tg-baqh\">2</td>\n    <td class=\"tg-baqh\">1</td>\n    <td class=\"tg-baqh\">1</td>\n    <td class=\"tg-baqh\">1</td>\n    <td class=\"tg-baqh\">1</td>\n    <td class=\"tg-baqh\">1</td>\n  </tr>\n</tbody>\n</table></p>\n<p>is 160, then the value of $$c\\in N$$ is</p>\n<p><strong>Hint:</strong> Use the variance formula for a frequency distribution. If variance is given, solve for the unknown frequency or value using the mean and second moment.</p>\n<p><strong>Formula:</strong></p>\n<p>$$\\sigma^2=\\frac{\\sum f_i(x_i-\\bar{x})^2}{\\sum f_i}=\\frac{\\sum f_i x_i^2}{\\sum f_i}-\\bar{x}^{\\,2}$$</p>",
