                "question": {
                  "en": {
                    "comprehension": null,
                    "direction": null,
                    "content": "<p>Let the set of all values of $$p$$, for which $$f(x)=\\left(p^2-6 p+8\\right)\\left(\\sin ^2 2 x-\\cos ^2 2 x\\right)+2(2-p) x+7$$ does not have any critical point, be the interval $$(a, b)$$. Then $$16 a b$$ is equal to _________.</p>\n<p><strong>Hint:</strong> Differentiate $f(x)$. For the function to be increasing on the stated interval, require $f'(x)\\geq0$ throughout; use the full interval, not just a point.</p>\n<p><strong>Formula:</strong></p>\n<p>$$f'(x)\\geq0\\ \\Longrightarrow\\ f\\text{ is non-decreasing}$$</p>",
                    "options": []
                  },
                  "hi": {
                    "direction": null,
                    "comprehension": null,
                    "content": "<p>माना $$p$$ के सभी मानों, जिनके लिए $$f(x)=\\left(p^2-6 p+8\\right)\\left(\\sin ^2 2 x-\\cos ^2 2 x\\right)+2(2-p) x+7$$ का एक भी क्रांतिक बिंदु नहीं है, का समुच्चय, अंतराल $$(a, b)$$ है। तो $$16 a b$$ बराबर है __________.</p>\n<p><strong>संकेत:</strong>  $f(x)$ का अवकलन करें। दिए गए interval पर increasing होने के लिए पूरे interval में $f'(x)\\geq0$ होना चाहिए; केवल एक बिंदु जाँचना पर्याप्त नहीं है.</p>\n<p><strong>सूत्र:</strong></p>\n<p>$$f'(x)\\geq0\\ \\Longrightarrow\\ f\\text{ non-decreasing है}$$</p>",
                    "options": []
                  }
                },
