                "permalink": "plet-a-b-and-c-be-three-points-on-the-parabola--jee-main-mathematics-trigonometric-functions-and-equations-mbnxbhxk3k34oqok",
                "question": {
                  "en": {
                    "comprehension": null,
                    "direction": null,
                    "content": "<p>Let $$A, B$$ and $$C$$ be three points on the parabola $$y^2=6 x$$ and let the line segment $$A B$$ meet the line $$L$$ through $$C$$ parallel to the $$x$$-axis at the point $$D$$. Let $$M$$ and $$N$$ respectively be the feet of the perpendiculars from $$A$$ and $$B$$ on $$L$$. Then $$\\left(\\frac{A M \\cdot B N}{C D}\\right)^2$$ is equal to __________.</p>\n<p><strong>Hint:</strong> For a hyperbola, use the relation between focal distance, semi-axes, and eccentricity. The foci of the given ellipse determine the focal distance of the hyperbola.</p>\n<p><strong>Formula:</strong></p>\n<p>$$c^2=a^2+b^2,\\qquad e=\\frac{c}{a},\\qquad \\text{axis lengths}=2a,\\,2b$$</p>",
                    "options": []
                  },
                  "hi": {
                    "direction": null,
                    "comprehension": null,
                    "content": "<p>माना परवलय $$y^2=6 x$$ पर तीन बिंदु $$A, B$$ तथा $$C$$ हैं और माना $$C$$ से होकर जाने वाली तथा $$x$$-अक्ष के समांतर रेखा $$L$$, रेखाखंड $$A B$$ को बिंदु $$D$$ पर मिलती है। माना $$A$$ तथा $$B$$ से रेखा $$L$$ पर डाले गए लम्बों के पाद क्रमशः $$M$$ तथा $$N$$ हैं। तो $$\\left(\\frac{A M \\cdot B N}{C D}\\right)^2$$ बराबर है _________.</p>\n<p><strong>संकेत:</strong> अतिपरवलय में नाभीय दूरी, अर्ध-अक्षों और उत्केन्द्रता का संबंध लगाएँ। दिए गए दीर्घवृत्त की नाभियाँ अतिपरवलय की नाभीय दूरी तय करती हैं.</p>\n<p><strong>सूत्र:</strong></p>\n<p>$$c^2=a^2+b^2,\\qquad e=\\frac{c}{a},\\qquad \\text{अक्षों की लंबाई}=2a,\\,2b$$</p>",
                    "options": []
                  }
                },
