                "question": {
                  "en": {
                    "comprehension": null,
                    "direction": null,
                    "content": "<p>Consider the circle $$C: x^2+y^2=4$$ and the parabola $$P: y^2=8 x$$. If the set of all values of $$\\alpha$$, for which three chords of the circle $$C$$ on three distinct lines passing through the point $$(\\alpha, 0)$$ are bisected by the parabola $$P$$ is the interval $$(p, q)$$, then $$(2 q-p)^2$$ is equal to __________.</p>\n<p><strong>Hint:</strong> Use the condition for a line to intersect a circle and parabola at the required number of points. Tangency occurs when the resulting quadratic has discriminant zero.</p>\n<p><strong>Formula:</strong></p>\n<p>$$\\Delta=b^2-4ac=0\\quad\\text{for tangency}$$</p>",
                    "options": []
                  },
                  "hi": {
                    "direction": null,
                    "comprehension": null,
                    "content": "<p>वृत्त $$C: x^2+y^2=4$$ तथा परवलय $$P: y^2=8 x$$ का विचार कीजिए। यदि $$\\alpha$$ के सभी मानों, जिनके लिए बिंदु $$(\\alpha, 0)$$ से होकर जाने वाली तीन भिन्न रेखाओं पर वृत्त $$C$$ की तीन जीवाएँ, परवलय $$P$$ द्वारा समद्विभाजित होती हैं, का समुच्चय अंतराल $$(p, q)$$ है, तो $$(2 q-p)^2$$ बराबर है ________.</p>\n<p><strong>संकेत:</strong> रेखा के circle और parabola को आवश्यक संख्या में काटने की शर्त लगाएँ। स्पर्शरेखा की स्थिति में प्राप्त quadratic का discriminant शून्य होता है.</p>\n<p><strong>सूत्र:</strong></p>\n<p>$$\\Delta=b^2-4ac=0\\quad\\text{स्पर्शरेखा के लिए}$$</p>",
                    "options": []
                  }
                },
