                "permalink": "pfor-a-differentiable-function-f-mathbbr-rightarrow-jee-main-mathematics-trigonometric-functions-and-equations-xro3dos12crncdsy",
                "question": {
                  "en": {
                    "comprehension": null,
                    "direction": null,
                    "content": "<p>For a differentiable function $$f: \\mathbb{R} \\rightarrow \\mathbb{R}$$, suppose $$f^{\\prime}(x)=3 f(x)+\\alpha$$, where $$\\alpha \\in \\mathbb{R}, f(0)=1$$ and $$\\lim _\\limits{x \\rightarrow-\\infty} f(x)=7$$. Then $$9 f\\left(-\\log _e 3\\right)$$ is equal to _________.</p>\n<p><strong>Hint:</strong> Differentiate the integral equation using the Fundamental Theorem of Calculus to obtain a differential relation. For a first-order linear ODE, use the integrating factor.</p>\n<p><strong>Formula:</strong></p>\n<p>$$\\frac{dy}{dx}+P(x)y=Q(x),\\qquad \\mathrm{I.F.}=e^{\\int P(x)\\,dx}$$</p>",
                    "options": []
                  },
                  "hi": {
                    "direction": null,
                    "comprehension": null,
                    "content": "<p>एक अवकलनीय फलन $$f: \\mathbb{R} \\rightarrow \\mathbb{R}$$ के लिए, माना $$f^{\\prime}(x)=3 f(x)+\\alpha$$, जहाँ $$\\alpha \\in \\mathbb{R}, f(0)=1$$ तथा $$\\lim _\\limits{x \\rightarrow-\\infty} f(x)=7$$ हें। तो $$9 f\\left(-\\log _e 3\\right)$$ बराबर हे __________.</p>\n<p><strong>संकेत:</strong> समाकल समीकरण का Fundamental Theorem of Calculus से अवकलन करके differential relation पाएँ। प्रथम कोटि linear ODE के लिए integrating factor लगाएँ.</p>\n<p><strong>सूत्र:</strong></p>\n<p>$$\\frac{dy}{dx}+P(x)y=Q(x),\\qquad \\mathrm{I.F.}=e^{\\int P(x)\\,dx}$$</p>",
                    "options": []
                  }
                },
                "section": [
                  "chapter",
                  "paper"
                ],
                "subject": "mathematics",
                "subjectGroup": null,
