                    "content": "<p>एक इलेक्ट्रॉनिक युक्ति का $$I$$-$$V$$ अभिलाक्षणिक चित्र में दर्शाया गया है। युक्ति है :</p>\n<p><img src=\"https://app-content.cdn.examgoal.net/fly/@width/image/jaoe38c1lxa0yr24/4c8921d6-64de-4518-989f-2d78feaa215e/5e5e7bc0-27bc-11ef-a0f5-fb78d7d87993/file-jaoe38c1lxa0yr25.png?format=png\" data-orsrc=\"https://app-content.cdn.examgoal.net/image/jaoe38c1lxa0yr24/4c8921d6-64de-4518-989f-2d78feaa215e/5e5e7bc0-27bc-11ef-a0f5-fb78d7d87993/file-jaoe38c1lxa0yr25.png\" loading=\"lazy\" style=\"max-width:100%;height:auto;display:block;margin:0 auto;max-height:40vh;vertical-align:baseline\" alt=\"JEE Main 2024 (Online) 9th April Evening Shift Physics - Semiconductor Question 52 Hindi\"></p>\n<p><strong>संकेत:</strong>  $I$-$V$ curve के आकार और polarity से device पहचानें। diode threshold के बाद forward bias में अधिक current देता है और reverse bias में बहुत कम leakage current देता है.</p>\n<p><strong>सूत्र:</strong></p>\n<p>$$I\\text{-}V\\text{ curve से device पहचानें}$$</p>",
