                    "content": "<p>A nucleus at rest disintegrates into two smaller nuclei with their masses in the ratio of $$2: 1$$. After disintegration they will move :</p>\n<p><strong>Hint:</strong> Use mass defect to calculate released energy. Compare energy per unit mass by using the appropriate nuclear reaction and converting atomic mass units to joules.</p>\n<p><strong>Formula:</strong></p>\n<p>$$E=\\Delta m\\,c^2,\\qquad 1\\,\\mathrm{u}\\,c^2\\approx 931.5\\,\\mathrm{MeV}$$</p>",
