                    "comprehension": null,
                    "content": "<p>विरामावस्था में एक नाभिक $$2: 1$$ के द्रव्यमान अनुपात में दो छोटे नाभिकों में विखण्डित होता है। विखण्डन के उपरान्त वे गति करेंगे:</p>\n<p><strong>संकेत:</strong> Mass defect से released energy निकालें। उपयुक्त nuclear reaction और atomic mass unit को joule में बदलकर प्रति इकाई द्रव्यमान ऊर्जा की तुलना करें.</p>\n<p><strong>सूत्र:</strong></p>\n<p>$$E=\\Delta m\\,c^2$$</p>",
