                    "direction": null,
                    "content": "<p>A spherical ball of radius $$1 \\times 10^{-4} \\mathrm{~m}$$ and density $$10^5 \\mathrm{~kg} / \\mathrm{m}^3$$ falls freely under gravity through a distance $$h$$ before entering a tank of water. If after entering in water the velocity of the ball does not change, then the value of $$h$$ is approximately:</p>\n<p>(The coefficient of viscosity of water is $$9.8 \\times 10^{-6} \\mathrm{~N} \\mathrm{~s} / \\mathrm{m}^2$$)</p>\n<p><strong>Hint:</strong> At terminal velocity, weight minus buoyancy equals viscous drag. For a small sphere in laminar flow, use Stokes' law.</p>\n<p><strong>Formula:</strong></p>\n<p>$$F_{\\mathrm{drag}}=6\\pi\\eta r v,\\qquad v_t=\\frac{2r^2(\\rho_s-\\rho_f)g}{9\\eta}$$</p>",
