                    "content": "<p>The de-Broglie wavelength associated with a particle of mass $$m$$ and energy $$E$$ is $$h / \\sqrt{2 m E}$$. The dimensional formula for Planck's constant is :</p>\n<p><strong>Hint:</strong> Write the dimensions of each quantity in the formula and equate powers of $M,L,T$. Dimensional analysis checks consistency but does not determine dimensionless constants.</p>\n<p><strong>Formula:</strong></p>\n<p>$$[E]=[M L^2 T^{-2}],\\qquad [h]=[M L^2 T^{-1}]$$</p>",
