                    "content": "<p>UV light of $$4.13 \\mathrm{~eV}$$ is incident on a photosensitive metal surface having work function $$3.13 \\mathrm{~eV}$$. The maximum kinetic energy of ejected photoelectrons will be:</p>\n<p><strong>Hint:</strong> Use Einstein's photoelectric equation. Maximum kinetic energy is photon energy minus work function; stopping potential is the kinetic energy per electron charge.</p>\n<p><strong>Formula:</strong></p>\n<p>$$K_{\\max}=h\\nu-\\phi=eV_s,\\qquad \\lambda_0=\\frac{hc}{\\phi}$$</p>",
