                "question": {
                  "en": {
                    "comprehension": null,
                    "direction": null,
                    "content": "<p>A straight magnetic strip has a magnetic moment of $$44 \\mathrm{~Am}^2$$. If the strip is bent in a semicircular shape, its magnetic moment will be ________  $$\\mathrm{Am}^2$$.</p>\n<p>(given $$\\pi=\\frac{22}{7}$$)</p>\n<p><strong>Hint:</strong> Magnetic moment equals current times the area of the loop. When the strip is bent into a semicircle, use the conserved strip length to find the radius and enclosed area.</p>\n<p><strong>Formula:</strong></p>\n<p>$$\\mu=IA,\\qquad \\mu_{\\mathrm{bar}}=m\\ell$$</p>",
                    "options": []
                  },
                  "hi": {
                    "direction": null,
                    "comprehension": null,
                    "content": "<p>एक सीधी चुम्बकीय पट्टी का चुम्बकीय आघूर्ण $$44 \\mathrm{~Am}^2$$ है। यदि इसे अर्द्धवृत्ताकार आकृति में मोड़ दिया जाये तो पट्टी का चुम्बकीय आघूर्ण ________ $$\\mathrm{Am}^2$$ होगा। (दिया है $$\\pi=\\frac{22}{7}$$)</p>\n<p><strong>संकेत:</strong> Magnetic moment loop current और area का गुणनफल है। strip को semicircle में मोड़ने पर उसकी लंबाई स्थिर रखकर radius और enclosed area निकालें.</p>\n<p><strong>सूत्र:</strong></p>\n<p>$$\\mu=IA$$</p>",
                    "options": []
                  }
                },
