                "question": {
                  "en": {
                    "comprehension": null,
                    "direction": null,
                    "content": "<p>A particle of mass $$0.50 \\mathrm{~kg}$$ executes simple harmonic motion under force $$F=-50(\\mathrm{Nm}^{-1}) x$$. The time period of oscillation is $$\\frac{x}{35} s$$. The value of $$x$$ is _________.</p> \n<p>(Given $$\\pi=\\frac{22}{7}$$)</p>\n<p><strong>Hint:</strong> Compare the restoring-force equation with $F=-kx$. Then use $\\omega=\\sqrt{k/m}$ and $T=2\\pi/\\omega$.</p>\n<p><strong>Formula:</strong></p>\n<p>$$\\omega=\\sqrt{\\frac{k}{m}},\\qquad T=2\\pi\\sqrt{\\frac{m}{k}}$$</p>",
                    "options": []
                  },
                  "hi": {
                    "direction": null,
                    "comprehension": null,
                    "content": "<p>0.50 किग्रा द्रव्यमान का एक कण किसी बल $$F=-50(\\mathrm{Nm}^{-1}) x$$ के अन्तर्गत सरल आवर्त गति करता है। दोलन का आवर्तकाल $$\\frac{x}{35} s$$ से है। $$x$$ का मान ________ है।</p>\n<p>(दिया है $$\\pi=\\frac{22}{7}$$)</p>\n<p><strong>संकेत:</strong> Restoring-force equation की तुलना $F=-kx$ से करें। फिर $\\omega=\\sqrt{k/m}$ और $T=2\\pi/\\omega$ लगाएँ.</p>\n<p><strong>सूत्र:</strong></p>\n<p>$$T=2\\pi\\sqrt{\\frac{m}{k}}$$</p>",
                    "options": []
                  }
                },
