                "question": {
                  "en": {
                    "comprehension": null,
                    "direction": null,
                    "content": "<p>At room temperature $$(27^{\\circ} \\mathrm{C})$$, the resistance of a heating element is $$50 \\Omega$$. The temperature coefficient of the material is $$2.4 \\times 10^{-4}{ }^{\\circ} \\mathrm{C}^{-1}$$. The temperature of the element, when its resistance is $$62 \\Omega$$, is __________$${ }^{\\circ} \\mathrm{C}$$.</p>\n<p><strong>Hint:</strong> Use the linear temperature dependence of resistance near room temperature. Convert the temperature difference to kelvin or Celsius degrees consistently.</p>\n<p><strong>Formula:</strong></p>\n<p>$$R=R_0\\left[1+\\alpha(T-T_0)\\right]$$</p>",
                    "options": []
                  },
                  "hi": {
                    "direction": null,
                    "comprehension": null,
                    "content": "<p>सामान्य तापमान $$(27^{\\circ} \\mathrm{C})$$ पर एक ऊष्मा तन्तु का प्रतिरोध $$50 \\Omega$$ है। पदार्थ का ताप गुणांक $$2.4 \\times 10^{-4}{ }^{\\circ} \\mathrm{C}^{-1}$$ है। $$62 \\Omega$$ प्रतिरोध होने पर तन्तु का तापमान ________ $${ }^{\\circ} \\mathrm{C}$$ है।</p>\n<p><strong>संकेत:</strong> Room temperature के पास resistance का linear temperature relation लगाएँ। temperature difference को kelvin या Celsius degree में संगत रूप से रखें.</p>\n<p><strong>सूत्र:</strong></p>\n<p>$$R=R_0\\left[1+\\alpha(T-T_0)\\right]$$</p>",
                    "options": []
                  }
                },
