                "permalink": "pa-circular-disc-reaches-from-top-to-bottom-of-an-inclined-jee-main-physics-motion-dxdzwhwiingnuijk",
                "question": {
                  "en": {
                    "comprehension": null,
                    "direction": null,
                    "content": "<p>A circular disc reaches from top to bottom of an inclined plane of length $$l$$. When it slips down the plane, it takes $$t \\mathrm{~s}$$. When it rolls down the plane then it takes $$\\left(\\frac{\\alpha}{2}\\right)^{1 / 2} t \\mathrm{~s}$$, where $$\\alpha$$ is _________.</p>\n<p><strong>Hint:</strong> Use energy conservation for rolling/sliding down the incline. For rolling without slipping, translational and rotational kinetic energies both contribute.</p>\n<p><strong>Formula:</strong></p>\n<p>$$mgh=\\frac{1}{2}mv^2+\\frac{1}{2}I\\omega^2,\\qquad v=\\omega R$$</p>",
                    "options": []
                  },
                  "hi": {
                    "direction": null,
                    "comprehension": null,
                    "content": "<p>एक वृत्ताकार चकती $$l$$ लम्बाई के एक आनत तल पर शिखर से निचले बिन्दु तक पहुँचती है। जब यह नीचे फिसलती है तो $$t$$ सेकंड समय लेती है। जब नीचे लुढ़कती है तो यह $$\\left(\\frac{\\alpha}{2}\\right)^{1 / 2} t$$ सेकंड समय लेती है, जहाँ $$\\alpha=$$ _______ है।</p>\n<p><strong>संकेत:</strong> Incline पर नीचे आने में energy conservation लगाएँ। बिना फिसले rolling में translational और rotational दोनों kinetic energies शामिल होती हैं.</p>\n<p><strong>सूत्र:</strong></p>\n<p>$$mgh=\\frac{1}{2}mv^2+\\frac{1}{2}I\\omega^2$$</p>",
                    "options": []
                  }
                },
