                    "content": "<p>Major product of the following reaction is</p>\n<p><img src=\"https://app-content.cdn.examgoal.net/fly/@width/image/1luxynapd/b0480c45-8036-4990-87ce-59c63c804331/77070430-f981-11ee-8926-03d723181fd1/file-1luxynapf.png?format=png\" data-orsrc=\"https://app-content.cdn.examgoal.net/image/1luxynapd/b0480c45-8036-4990-87ce-59c63c804331/77070430-f981-11ee-8926-03d723181fd1/file-1luxynapf.png\" loading=\"lazy\" style=\"max-width:100%;height:auto;display:block;margin:0 auto;max-height:40vh;vertical-align:baseline\" alt=\"JEE Main 2024 (Online) 9th April Evening Shift Chemistry - Compounds Containing Nitrogen Question 61 English\"></p>\n<p><strong>Hint:</strong> Identify the reagent sequence and functional group in the reaction. For diazonium chemistry, temperature and substitution conditions determine the major product.</p>\n<p><strong>Formula:</strong></p>\n<p>$$\\mathrm{ArN_2^+X^-}\\xrightarrow[\\text{appropriate conditions}]{}\\text{substitution product}$$</p>",
