                    "direction": null,
                    "content": "<p>The incorrect statement regarding ethyne is</p>\n<p><strong>Hint:</strong> Check ethyne's structure, acidity of terminal hydrogen, and characteristic addition reactions. Distinguish reactions of alkynes from those of alkenes.</p>\n<p><strong>Formula:</strong></p>\n<p>$$\\mathrm{HC\\equiv CH}+2\\mathrm{H_2}\\xrightarrow{\\mathrm{Ni}}\\mathrm{CH_3CH_3}$$</p>",
