                      {
                        "identifier": "C",
                        "content": "The $$\\mathrm{C}-\\mathrm{C}$$ bond in ethyne is shorter than that in ethene\n"
                      },
                      {
                        "identifier": "D",
                        "content": "Ethyne is linear"
                      }
