                    "comprehension": null,
                    "content": "<p>सूची I का मिलान सूची II से करें:</p>\n<p><style type=\"text/css\">\n.tg  {border-collapse:collapse;border-spacing:0;}\n.tg td{border-color:black;border-style:solid;border-width:1px;font-family:Arial, sans-serif;font-size:14px;\n  overflow:hidden;padding:10px 5px;word-break:normal;}\n.tg th{border-color:black;border-style:solid;border-width:1px;font-family:Arial, sans-serif;font-size:14px;\n  font-weight:normal;overflow:hidden;padding:10px 5px;word-break:normal;}\n.tg .tg-c3ow{border-color:inherit;text-align:center;vertical-align:top}\n.tg .tg-7btt{border-color:inherit;font-weight:bold;text-align:center;vertical-align:top}\n.tg .tg-0pky{border-color:inherit;text-align:left;vertical-align:top}\n</style>\n<table class=\"tg\" style=\"undefined;table-layout: fixed; width: 618px\"><colgroup>\n<col style=\"width: 78px\">\n<col style=\"width: 206px\">\n<col style=\"width: 83px\">\n<col style=\"width: 251px\">\n</colgroup>\n<thead>\n  <tr>\n    <th class=\"tg-7btt\"></th>\n    <th class=\"tg-7btt\">सूची I<br></th>\n    <th class=\"tg-7btt\"></th>\n    <th class=\"tg-7btt\">सूची II<br></th>\n  </tr></thead>\n<tbody>\n  <tr>\n    <td class=\"tg-c3ow\">(A)</td>\n    <td class=\"tg-0pky\">गलनांक [K]</td>\n    <td class=\"tg-c3ow\">(I)</td>\n    <td class=\"tg-0pky\">$$\\mathrm{Tl &gt; In &gt; Ga &gt; Al &gt; B}$$</td>\n  </tr>\n  <tr>\n    <td class=\"tg-c3ow\">(B)</td>\n    <td class=\"tg-0pky\">आयनिक त्रिज्या $$\\left[\\mathrm{M}^{+3} / \\mathrm{pm}\\right]$$</td>\n    <td class=\"tg-c3ow\">(II)</td>\n    <td class=\"tg-0pky\">$$\\mathrm{B}&gt;\\mathrm{Tl}&gt;\\mathrm{Al} \\approx \\mathrm{Ga}&gt;\\mathrm{In}$$</td>\n  </tr>\n  <tr>\n    <td class=\"tg-c3ow\">(C)</td>\n    <td class=\"tg-0pky\">$$\\Delta_{\\mathrm{i}} \\mathrm{H}_1\\left[\\mathrm{~kJ} \\mathrm{~mol}^{-1}\\right]$$</td>\n    <td class=\"tg-c3ow\">(III)</td>\n    <td class=\"tg-0pky\">$$\\mathrm{Tl}&gt;\\mathrm{In}&gt;\\mathrm{Al}&gt;\\mathrm{Ga}&gt;\\mathrm{B}$$</td>\n  </tr>\n  <tr>\n    <td class=\"tg-c3ow\">(D)</td>\n    <td class=\"tg-0pky\">परमाणु त्रिज्या [pm]</td>\n    <td class=\"tg-c3ow\">(IV)</td>\n    <td class=\"tg-0pky\">$$\\mathrm{B}&gt;\\mathrm{Al}&gt;\\mathrm{Tl}&gt;\\mathrm{In}&gt;\\mathrm{Ga}$$</td>\n  </tr>\n</tbody></table></p>\n<p>नीचे दिए गए विकल्पों में से सही उत्तर को चुनें:</p>\n<p><strong>संकेत:</strong> Periodic trends के साथ subshell stability और electron pairing का ध्यान रखें। successive ionisation energies बढ़ती हैं और सभी valence electrons निकलने के बाद बड़ा jump आता है.</p>\n<p><strong>सूत्र:</strong></p>\n<p>$$I_1<I_2<I_3<\\cdots$$</p>",
