"tg-0pky\">$$d^2sp^3$$</td>\n  </tr>\n</tbody>\n</table></p>\n<p>Choose the correct answer from the options given below:</p>\n<p><strong>Hint:</strong> Determine the number of donor atoms attached to the metal and the coordination number. EDTA is commonly hexadentate, binding through six donor atoms.</p>\n<p><strong>Formula:</strong></p>\n<p>$$\\text{Coordination number}=\\text{number of donor atoms bonded to metal}$$</p>",
