                "question": {
                  "en": {
                    "comprehension": null,
                    "direction": null,
                    "content": "<p>The correct stability order of the following resonance structures of $$\\mathrm{CH}_3-\\mathrm{CH}=\\mathrm{CH}-\\mathrm{CHO}$$ is</p>\n<p><img src=\"https://app-content.cdn.examgoal.net/fly/@width/image/1luxvg3ct/c5d496aa-ff44-448a-89e9-e87df76fce3a/f34c4ad0-f974-11ee-a5bc-b108889e7d03/file-1luxvg3cu.png?format=png\" data-orsrc=\"https://app-content.cdn.examgoal.net/image/1luxvg3ct/c5d496aa-ff44-448a-89e9-e87df76fce3a/f34c4ad0-f974-11ee-a5bc-b108889e7d03/file-1luxvg3cu.png\" loading=\"lazy\" style=\"max-width:100%;height:auto;display:block;margin:0 auto;max-height:40vh;vertical-align:baseline\" alt=\"JEE Main 2024 (Online) 9th April Evening Shift Chemistry - Basics of Organic Chemistry Question 92 English\"></p>\n<p><strong>Hint:</strong> Rank resonance contributors by octet completion, number of covalent bonds, and placement of charge. Delocalisation that places negative charge on an electronegative atom is generally favoured.</p>\n<p><strong>Formula:</strong></p>\n<p>$$\\text{greater resonance stabilisation}\\Rightarrow\\text{lower energy}$$</p>",
                    "options": [
                      {
                        "identifier": "A",
                        "content": "$$\\text { II }>\\text { III }>\\text { I }$$"
                      },
                      {
                        "identifier": "B",
                        "content": "$$\\text { II }>\\text { I }>\\text { III }$$"
                      },
                      {
                        "identifier": "C",
                        "content": "$$\\text { III }>\\text { II }>\\text { I }$$"
                      },
                      {
                        "identifier": "D",
                        "content": "$$\\text { I }>\\text { II }>\\text { III }$$"
                      }
                    ]
                  },
                  "hi": {
                    "comprehension": null,
                    "direction": null,
                    "content": "<p>$$\\mathrm{CH}_3-\\mathrm{CH}=\\mathrm{CH}-\\mathrm{CHO}$$ की निम्नलिखित अनुनादी संरचनाओं के स्थायित्व का सही क्रम है:</p>\n<p><img src=\"https://app-content.cdn.examgoal.net/fly/@width/image/1luxvg3ct/c5d496aa-ff44-448a-89e9-e87df76fce3a/f34c4ad0-f974-11ee-a5bc-b108889e7d03/file-1luxvg3cu.png?format=png\" data-orsrc=\"https://app-content.cdn.examgoal.net/image/1luxvg3ct/c5d496aa-ff44-448a-89e9-e87df76fce3a/f34c4ad0-f974-11ee-a5bc-b108889e7d03/file-1luxvg3cu.png\" loading=\"lazy\" style=\"max-width:100%;height:auto;display:block;margin:0 auto;max-height:40vh;vertical-align:baseline\" alt=\"JEE Main 2024 (Online) 9th April Evening Shift Chemistry - Basics of Organic Chemistry Question 92 Hindi\"></p>\n<p><strong>संकेत:</strong> Resonance contributors को octet completion, covalent bonds की संख्या और charge की स्थिति से rank करें। अधिक electronegative atom पर negative charge का delocalisation सामान्यतः अनुकूल है.</p>\n<p><strong>सूत्र:</strong></p>\n<p>$$\\text{अधिक resonance stabilisation}\\Rightarrow\\text{कम ऊर्जा}$$</p>",
                    "options": [
                      {
                        "identifier": "A",
                        "content": "$$\\text { II }>\\text { III }>\\text { I }$$"
                      },
                      {
                        "identifier": "B",
                        "content": "$$\\text { II }>\\text { I }>\\text { III }$$"
                      },
                      {
                        "identifier": "C",
                        "content": "$$\\text { III }>\\text { II }>\\text { I }$$"
                      },
                      {
                        "identifier": "D",
                        "content": "$$\\text { I }>\\text { II }>\\text { III }$$"
                      }
                    ]
                  }
                },
