                "question": {
                  "en": {
                    "comprehension": null,
                    "direction": null,
                    "content": "<p>Given below are two statements :</p>\n<p>Statement I : The higher oxidation states are more stable down the group among transition elements unlike p-block elements.</p>\n<p>Statement II : Copper can not liberate hydrogen from weak acids.</p>\n<p>In the light of the above statements, choose the correct answer from the options given below :</p>\n<p><strong>Hint:</strong> Transition-metal properties arise from partially filled d orbitals. Compare oxidation-state stability and standard trends down a group rather than assuming one universal order.</p>\n<p><strong>Formula:</strong></p>\n<p>$$\\text{Transition element: partially filled }d\\text{ subshell in atom or common ion}$$</p>",
                    "options": [
                      {
                        "identifier": "A",
                        "content": "Statement I is true but Statement II is false\n"
                      },
                      {
                        "identifier": "B",
                        "content": "Both Statement I and Statement II are false\n"
                      },
                      {
                        "identifier": "C",
                        "content": "Both Statement I and Statement II are true\n"
                      },
                      {
                        "identifier": "D",
                        "content": "Statement I is false but Statement II is true"
                      }
                    ]
                  },
                  "hi": {
                    "direction": null,
                    "comprehension": null,
                    "content": "<p>नीचे दो कथन दिए गए हैं:</p>\n<p>कथन I : p-ब्लॉक तत्वों के विपरीत, संक्रमण तत्वों में समूह में नीचे आने पर उच्च ऑक्सीकरण अवस्थाएँ अधिक स्थायी होती हैं।</p>\n<p>कथन II : कॉपर दुर्बल अम्लों से हाइड्रोजन निर्मुक्त नहीं करा सकता है।</p>\n<p>उपर्युक्त कथनों के संदर्भ में नीचे दिए गए विकल्पों में से सर्वाधिक उपयुक्त उत्तर चुनें:</p>\n<p><strong>संकेत:</strong> Transition-metal के गुण partially filled d orbitals से आते हैं। oxidation-state stability और group में नीचे जाने के trends की तुलना करें.</p>\n<p><strong>सूत्र:</strong></p>\n<p>$$\\text{Transition element: atom या सामान्य ion में partially filled }d\\text{ subshell}$$</p>",
                    "options": [
                      {
                        "identifier": "A",
                        "content": "कथन $$\\mathrm{I}$$ सही है परन्तु कथन $$\\mathrm{II}$$ गलत है।\n"
                      },
                      {
                        "identifier": "B",
                        "content": "दोनों कथन I तथा कथन II गलत हैं।\n"
                      },
                      {
                        "identifier": "C",
                        "content": "दोनों कथन I तथा कथन II सही हैं।\n"
                      },
                      {
                        "identifier": "D",
                        "content": "कथन I गलत है परन्तु कथन II सही है।"
                      }
                    ]
                  }
                },
