                  "en": {
                    "comprehension": null,
                    "direction": null,
                    "content": "<p>A transition metal '$$\\mathrm{M}$$' among $$\\mathrm{Sc}, \\mathrm{Ti}, \\mathrm{V}, \\mathrm{Cr}, \\mathrm{Mn}$$ and $$\\mathrm{Fe}$$ has the highest second ionisation enthalpy. The spin-only magnetic moment value of $$\\mathrm{M}^{+}$$ ion is _______ BM (Nearest integer)</p>\n<p>(Given atomic number $$\\mathrm{Sc}: 21, \\mathrm{Ti}: 22, \\mathrm{~V}: 23, \\mathrm{Cr}: 24, \\mathrm{Mn}: 25, \\mathrm{Fe}: 26$$)</p>\n<p><strong>Hint:</strong> Transition-metal properties arise from partially filled d orbitals. Compare oxidation-state stability and standard trends down a group rather than assuming one universal order.</p>\n<p><strong>Formula:</strong></p>\n<p>$$\\text{Transition element: partially filled }d\\text{ subshell in atom or common ion}$$</p>",
                    "options": []
                  },
                  "hi": {
                    "direction": null,
                    "comprehension": null,
                    "content": "<p>$$\\mathrm{Sc}, \\mathrm{Ti}, \\mathrm{V}, \\mathrm{Cr}, \\mathrm{Mn}$$ एवं $$\\mathrm{Fe}$$ में से किसी संक्रमण धातु '$$\\mathrm{M}$$' की द्वितीय आयनन एन्थैल्पी सर्वाधिक है। $$\\mathrm{M}^{+}$$ आयन का 'प्रचक्रण मात्र' चुम्बकीय आघूर्ण है: __________ $$\\mathrm{BM}$$ (निकटतम पूर्णांक में)</p>\n<p>(दिया गया हैः परमाणु क्रमांक: $$\\mathrm{Sc}: 21, \\mathrm{Ti}: 22, \\mathrm{~V}: 23, \\mathrm{Cr}: 24, \\mathrm{Mn}: 25, \\mathrm{Fe}: 26$$)</p>\n<p><strong>संकेत:</strong> Transition-metal के गुण partially filled d orbitals से आते हैं। oxidation-state stability और group में नीचे जाने के trends की तुलना करें.</p>\n<p><strong>सूत्र:</strong></p>\n<p>$$\\text{Transition element: atom या सामान्य ion में partially filled }d\\text{ subshell}$$</p>",
                    "options": []
                  }
