                    "content": "<p>$$\\mathrm{O}_2, \\mathrm{O}_2^{+}$$ एवं $$\\mathrm{O}_2^{-}$$ के $$\\left(\\pi^*\\right)$$ आण्विक कक्षकों में पाए जाने वाले इलेक्ट्रॉनों की कुल संख्या हैः _________.</p>\n<p><strong>संकेत:</strong> Molecular orbitals को बढ़ती ऊर्जा में Pauli principle और Hund's rule के अनुसार भरें। हर species में antibonding $\\pi^*$ orbitals के electrons अलग गिनें.</p>\n<p><strong>सूत्र:</strong></p>\n<p>$$\\text{Bond order}=\\frac{N_b-N_a}{2}$$</p>",
                    "options": []
